@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(0 0% 100.0%);
  --color-foreground: hsl(33.3 27.3% 6.5%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(33.3 27.3% 6.5%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(33.3 27.3% 6.5%);
  --color-primary: hsl(213.2 100.0% 43.9%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(210.0 27.3% 95.7%);
  --color-secondary-foreground: hsl(33.3 27.3% 6.5%);
  --color-muted: hsl(210.0 27.3% 95.7%);
  --color-muted-foreground: hsl(210.0 15.2% 69.0%);
  --color-accent: hsl(210.0 27.3% 95.7%);
  --color-accent-foreground: hsl(200.8 26.0% 19.6%);
  --color-destructive: hsl(349.9 80.2% 49.4%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(210.0 13.0% 91.0%);
  --color-input: hsl(212.0 17.2% 82.9%);
  --color-ring: hsl(213.2 100.0% 43.9%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(0 0% 100.0%);
  --color-foreground: hsl(33.3 27.3% 6.5%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(33.3 27.3% 6.5%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(33.3 27.3% 6.5%);
  --color-primary: hsl(213.2 100.0% 43.9%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(210.0 27.3% 95.7%);
  --color-secondary-foreground: hsl(33.3 27.3% 6.5%);
  --color-muted: hsl(210.0 27.3% 95.7%);
  --color-muted-foreground: hsl(210.0 15.2% 69.0%);
  --color-accent: hsl(210.0 27.3% 95.7%);
  --color-accent-foreground: hsl(200.8 26.0% 19.6%);
  --color-destructive: hsl(349.9 80.2% 49.4%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(210.0 13.0% 91.0%);
  --color-input: hsl(212.0 17.2% 82.9%);
  --color-ring: hsl(213.2 100.0% 43.9%);
    }

    @variant dark {
  --color-background: hsl(240.0 2.9% 6.9%);
  --color-foreground: hsl(210.0 10.3% 88.6%);
  --color-card: hsl(225.0 4.8% 16.5%);
  --color-card-foreground: hsl(210.0 10.3% 88.6%);
  --color-popover: hsl(240.0 4.6% 12.7%);
  --color-popover-foreground: hsl(210.0 10.3% 88.6%);
  --color-primary: hsl(209.4 99.1% 57.3%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(240.0 4.6% 12.7%);
  --color-secondary-foreground: hsl(210.0 10.3% 88.6%);
  --color-muted: hsl(240.0 4.6% 12.7%);
  --color-muted-foreground: hsl(216.9 5.5% 46.1%);
  --color-accent: hsl(225.0 4.8% 16.5%);
  --color-accent-foreground: hsl(210.0 10.3% 88.6%);
  --color-destructive: hsl(353.0 90.4% 59.2%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(240.0 4.7% 21.0%);
  --color-input: hsl(216.0 6.4% 30.6%);
  --color-ring: hsl(209.4 99.1% 57.3%);
    }
  }
}
